#include <set>
#include <iostream>

int main() {
    std::set<int> c = {10, 20, 40, 50};

    // Search for 30 (not present)
    auto lb30 = c.lower_bound(30);
    auto ub30 = c.upper_bound(30);

    // Both point to the successor (40)
    std::cout << "LB(30): " << *lb30 << std::endl;
    std::cout << "UB(30): " << *ub30 << std::endl;

    // Search for 20 (present)
    auto lb20 = c.lower_bound(20); // points to 20 (>= 20)
    auto ub20 = c.upper_bound(20); // points to 40 (> 20)
    std::cout << "LB(20): " << *lb20 << std::endl;
    std::cout << "UB(20): " << *ub20 << std::endl;
}
